/* Operations prototype. All records and changes stay in the current browser. */
let adminState={search:'',filter:'Todos',section:'',globalSearch:''};
const adminNav=[['','Visão geral','spark'],['pedidos','Pedidos','bag'],['assinaturas','Assinaturas','gift'],['producao','Produção','box'],['expedicao','Expedição','truck'],['produtos','Produtos e estoque','box'],['edicoes','Edições do clube','gift'],['clientes','Clientes','user'],['financeiro','Financeiro','card'],['suporte','Atendimentos','chat'],['comunidade','Mural de orações','heart'],['marketing','Oração diária','mail'],['relatorios','Relatórios','filter'],['equipe','Equipe e perfis','user'],['configuracoes','Configurações','filter']];
const adminNames=Object.fromEntries(adminNav.map(([p,n])=>[p,n]));
function adminTable(headers,rows){return `<div class="admin-table-wrap"><table class="admin-table"><thead><tr>${headers.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}"><div class="admin-empty">Nenhum registro com esses filtros. Tente outro termo ou selecione Todos.</div></td></tr>`}</tbody></table></div>`}
function adminHeading(title,description,actions=''){return `<div class="admin-page-heading"><div><h1>${title}</h1><p>${description}</p></div><div class="row wrap">${actions}</div></div>`}
function adminToolbar(statuses=['Todos']){return `<form class="admin-toolbar" data-form="admin-filter"><div class="admin-search-box">${icon('search')}<input name="search" type="search" value="${esc(adminState.search)}" placeholder="Buscar nesta lista" aria-label="Buscar nesta lista"></div><select name="status" aria-label="Filtrar por situação">${statuses.map(x=>`<option ${adminState.filter===x?'selected':''}>${x}</option>`).join('')}</select><button class="btn secondary small">Buscar</button><button type="button" class="text-btn" data-admin="clear-filter">Limpar</button></form>`}
function adminFiltered(items,extra=()=>true){return items.filter(x=>(adminState.filter==='Todos'||x.status===adminState.filter||x.type===adminState.filter||x.category===adminState.filter)&&(!adminState.search||JSON.stringify({...x,client:opClient(x.customerId)?.name}).toLocaleLowerCase('pt-BR').includes(adminState.search.toLocaleLowerCase('pt-BR')))&&extra(x))}
function adminMoneyStats(){const paid=ops.charges.filter(x=>x.status==='Pago').reduce((a,x)=>a+x.amount,0),pending=ops.charges.filter(x=>['Pendente','Recusado'].includes(x.status)).reduce((a,x)=>a+x.amount,0),expenses=ops.expenses.filter(x=>x.status==='Pago').reduce((a,x)=>a+x.amount,0),mrr=ops.subscriptions.filter(s=>s.status==='Ativa').reduce((a,x)=>a+x.price,0);return{paid,pending,expenses,mrr}}
function adminStats(items){return `<div class="admin-stats">${items.map(([label,value,note])=>`<div class="admin-stat"><span>${label}</span><strong>${value}</strong><small>${note||'Dados de demonstração'}</small></div>`).join('')}</div>`}
function adminShell(route=[]){const section=route[0]||'',id=route[1];if(section!==adminState.section){adminState.section=section;adminState.search='';adminState.filter='Todos'}const alerts=ops.tickets.filter(t=>t.status!=='Resolvido').length+ops.charges.filter(c=>['Pendente','Recusado'].includes(c.status)).length;let body=section===''?adminOverview():section==='pedidos'?id?adminOrderDetail(id):adminOrders():section==='assinaturas'?id?adminSubscriptionDetail(id):adminSubscriptions():section==='clientes'?id?adminClientDetail(id):adminClients():section==='producao'?adminProduction():section==='expedicao'?adminShipping():section==='financeiro'?adminFinance():section==='produtos'?adminProducts():section==='edicoes'?adminEditions():section==='suporte'?adminSupport(id):section==='comunidade'?adminCommunity():section==='marketing'?adminMarketing():section==='relatorios'?adminReports():section==='equipe'?adminTeam():section==='configuracoes'?adminSettings():section==='atividade'?adminActivity():section==='busca'?adminGlobalResults():adminOverview();return `<div class="admin-app"><aside class="admin-sidebar"><div class="admin-brand">${logo()}<span>gestão</span></div><nav aria-label="Administração">${adminNav.map(([p,n,ic])=>`<a href="#/admin${p?'/'+p:''}" class="${p===section?'active':''}">${icon(ic)}<span>${n}</span>${p==='suporte'&&ops.tickets.some(t=>t.status!=='Resolvido')?`<small>${ops.tickets.filter(t=>t.status!=='Resolvido').length}</small>`:''}</a>`).join('')}</nav><div class="admin-sidebar-bottom"><a href="#/">${icon('arrow')}Voltar para a loja</a><button class="admin-session-end" data-auth="logout-admin">${icon('logout')}Sair da gestão</button><p>Ambiente de demonstração<br>sem acesso a operações reais</p></div></aside><div class="admin-workspace"><header class="admin-topbar"><span>${adminNames[section]||'Operação'}</span><form data-form="admin-global-search" class="admin-global-search">${icon('search')}<input name="query" placeholder="Buscar cliente, pedido ou assinatura" aria-label="Busca geral do administrador" value="${esc(adminState.globalSearch)}"><button class="icon-btn" aria-label="Buscar na operação">${icon('arrow')}</button></form><div class="admin-topbar-actions"><span class="admin-demo-badge">Dados demonstrativos</span><details class="admin-notifications"><summary aria-label="Abrir pendências">${icon('chat')}<small>${alerts}</small></summary><div><h3>Precisam de atenção</h3><a href="#/admin/financeiro">${ops.charges.filter(c=>['Pendente','Recusado'].includes(c.status)).length} cobranças pendentes</a><a href="#/admin/suporte">${ops.tickets.filter(t=>t.status!=='Resolvido').length} atendimentos em aberto</a><a href="#/admin/producao">${ops.jobs.filter(j=>j.stage!=='Pronto').length} ordens na produção</a></div></details><a class="admin-avatar" href="#/admin/equipe" aria-label="Equipe de demonstração">AD</a></div></header><main id="main" class="admin-main">${body}</main><footer class="admin-footnote">Mãos em Oração · painel de demonstração local · pagamentos, envios, permissões e mensagens são simulados.</footer></div></div>`}
function adminOverview(){const f=adminMoneyStats(),active=ops.subscriptions.filter(x=>x.status==='Ativa').length,queue=ops.orders.filter(x=>!['Entregue','Cancelado'].includes(x.status)),last=ops.orders.slice(0,6);return `${adminHeading('Tudo pronto para um novo dia.','Acompanhe a loja e o clube, da primeira escolha até a entrega.',`<button class="btn secondary small" data-admin="new-order">${icon('plus')}Criar pedido</button><a class="btn small" href="#/admin/edicoes">Preparar edição do clube ${icon('arrow')}</a>`)}${adminStats([['Pedidos em andamento',queue.length,'Loja + clube'],['Assinaturas ativas',active,'Clientes com plano ativo'],['Receita mensal do clube',money(f.mrr),'Projeção das assinaturas ativas'],['A receber',money(f.pending),'Cobranças pendentes da simulação']])}<div class="admin-dashboard-grid"><section class="admin-panel"><div class="admin-panel-heading"><h2>O caminho de cada pedido</h2><a href="#/admin/pedidos">Ver todos ${icon('arrow')}</a></div><div class="admin-flow">${[['Aguardando pagamento','Pagamento'],['Confirmado','Confirmados'],['Em produção','Produção'],['Em acabamento','Acabamento'],['Pronto para envio','Expedição'],['Enviado','A caminho']].map(([s,t])=>`<a href="#/admin/${s==='Aguardando pagamento'?'financeiro':s==='Pronto para envio'||s==='Enviado'?'expedicao':s==='Em produção'||s==='Em acabamento'?'producao':'pedidos'}"><strong>${ops.orders.filter(o=>o.status===s).length}</strong><span>${t}</span></a>`).join('')}</div><div class="admin-panel-subhead"><h3>Pedidos recentes</h3></div>${adminTable(['Pedido','Cliente','Origem','Valor','Situação'],last.map(o=>[`<a href="#/admin/pedidos/${o.id}" class="admin-link">${esc(o.id)}</a>`,esc(opClient(o.customerId)?.name||'Cliente'),opStatus(o.type),money(o.total),opStatus(o.status)]))}</section><aside class="admin-panel admin-attention"><h2>Seu próximo passo</h2><a href="#/admin/financeiro">${icon('card')}<span><strong>Revisar pagamentos</strong><small>${ops.charges.filter(x=>['Pendente','Recusado'].includes(x.status)).length} cobranças precisam de atenção.</small></span>${icon('chevron')}</a><a href="#/admin/producao">${icon('box')}<span><strong>Organizar a produção</strong><small>${ops.jobs.filter(x=>x.stage!=='Pronto').length} tarefas na fila e nas máquinas.</small></span>${icon('chevron')}</a><a href="#/admin/suporte">${icon('chat')}<span><strong>Acolher os clientes</strong><small>${ops.tickets.filter(t=>t.status!=='Resolvido').length} atendimentos abertos.</small></span>${icon('chevron')}</a><a href="#/admin/edicoes">${icon('gift')}<span><strong>${esc(ops.settings.edition)}</strong><small>Edição de ${opMonth(ops.settings.editionMonth+'-08')}, envio no dia ${ops.settings.dispatchDay}.</small></span>${icon('chevron')}</a></aside></div><section class="admin-panel" style="margin-top:24px"><div class="admin-panel-heading"><h2>Atividade da operação</h2><a href="#/admin/atividade">Ver histórico ${icon('arrow')}</a></div>${adminAuditList(5)}</section>`}
function adminOrders(){const list=adminFiltered(ops.orders);return `${adminHeading('Pedidos','Loja e clube em uma única operação.',`<button class="btn secondary small" data-admin="export" data-kind="pedidos">Exportar CSV</button><button class="btn small" data-admin="new-order">${icon('plus')}Novo pedido</button>`)}${adminToolbar(['Todos','Clube','Loja','Aguardando pagamento','Confirmado','Em produção','Em acabamento','Pronto para envio','Enviado','Entregue','Cancelado'])}${adminTable(['Pedido / data','Cliente','Origem','Itens','Total','Situação',''],list.map(o=>[`<a class="admin-link" href="#/admin/pedidos/${o.id}">${esc(o.id)}</a><small>${opDate(o.created)}</small>`,`<a href="#/admin/clientes/${o.customerId}">${esc(opClient(o.customerId)?.name||'Cliente')}</a>`,opStatus(o.type),o.items.reduce((a,x)=>a+x.qty,0),money(o.total),opStatus(o.status),`<a class="admin-row-action" href="#/admin/pedidos/${o.id}">Abrir ${icon('chevron')}</a>`]))}`}
function adminOrderDetail(id){const o=opOrder(id);if(!o)return adminNotFound();const c=opClient(o.customerId),charge=ops.charges.find(x=>x.id===o.chargeId);return `${adminHeading(esc(o.id),'Criado em '+opDate(o.created)+' · '+o.type,`<a class="btn secondary small" href="#/admin/pedidos">Voltar aos pedidos</a><button class="btn small" data-admin="edit-order" data-id="${o.id}">Atualizar pedido</button>`)}<div class="admin-detail-grid"><section class="admin-panel"><div class="row between wrap"><h2>Itens do pedido</h2>${opStatus(o.status)}</div>${adminTable(['Peça','Detalhes','Qtd.','Valor'],o.items.map(x=>[`<div class="admin-product-cell">${photo(x.img,'',x.name)}<span>${esc(x.name)}</span></div>`,`${esc(x.color)} · ${esc(x.size)}`,x.qty,money(x.price*x.qty)]))}<div class="admin-order-total"><span>Total cobrado ${o.type==='Clube'?'no plano mensal':''}</span><strong>${money(o.total)}</strong></div><div class="admin-inline-actions">${['Confirmado','Em produção','Em acabamento'].includes(o.status)?`<button class="btn small" data-admin="production-add" data-id="${o.id}">Enviar para produção</button>`:''}${o.status==='Pronto para envio'?`<button class="btn small" data-admin="ship-order" data-id="${o.id}">Preparar envio</button>`:''}${o.tracking?`<button class="btn secondary small" data-admin="label" data-id="${o.id}">Ver etiqueta de demonstração</button>`:''}</div><h3 style="margin-top:25px">Observações internas</h3><p class="admin-note">${esc(o.notes||'Nenhuma observação adicionada.')}</p></section><aside class="stack"><section class="admin-panel"><h2>Cliente e entrega</h2><a href="#/admin/clientes/${c.id}" class="admin-link">${esc(c.name)}</a><p>${esc(c.email)}</p><hr><p>${esc(o.address.street)}, ${esc(o.address.number)}<br>${esc(o.address.city)}/${esc(o.address.state)} · ${esc(o.address.cep)}</p><small>Expedição prevista: ${opDate(o.due)}</small></section><section class="admin-panel"><h2>Pagamento</h2>${charge?`${opStatus(charge.status)}<p>${money(charge.amount)} · ${charge.method==='card'?'Cartão demo':'Pix / simulação'}</p>${['Pendente','Recusado'].includes(charge.status)?`<button class="btn full small" data-admin="pay-charge" data-id="${charge.id}">Simular recebimento</button>`:''}<a class="text-btn" href="#/admin/financeiro">Abrir financeiro</a>`:'<p>Sem cobrança associada.</p>'}${o.subscriptionId?`<a class="text-btn" href="#/admin/assinaturas/${o.subscriptionId}">Ver assinatura vinculada</a>`:''}</section></aside></div>`}
function adminSubscriptions(){const list=adminFiltered(ops.subscriptions),f=adminMoneyStats();return `${adminHeading('Assinaturas','Acompanhe o vínculo mensal, as renovações e cada edição.',`<button class="btn secondary small" data-admin="export" data-kind="assinaturas">Exportar CSV</button><a class="btn small" href="#/clube">Ver página do clube ${icon('arrow')}</a>`)}${adminStats([['Ativas',ops.subscriptions.filter(s=>s.status==='Ativa').length],['Receita mensal projetada',money(f.mrr),'Somente contratos ativos'],['Pausadas',ops.subscriptions.filter(s=>s.status==='Pausada').length],['Pagamento pendente',ops.subscriptions.filter(s=>s.status==='Pagamento pendente').length]])}${adminToolbar(['Todos','Ativa','Pausada','Pagamento pendente','Cancelada'])}${adminTable(['Assinatura','Cliente','Perfil','Mensalidade','Próxima renovação','Situação',''],list.map(s=>[`<a class="admin-link" href="#/admin/assinaturas/${s.id}">${s.id}</a>`,esc(opClient(s.customerId)?.name),esc(s.profile),money(s.price),['Pausada','Cancelada'].includes(s.status)?'Interrompida':opDate(s.nextRenewal),opStatus(s.status),`<a class="admin-row-action" href="#/admin/assinaturas/${s.id}">Gerenciar ${icon('chevron')}</a>`]))}`}
function adminSubscriptionDetail(id){const s=opSubscription(id);if(!s)return adminNotFound();const c=opClient(s.customerId),list=ops.orders.filter(o=>o.subscriptionId===id);return `${adminHeading(s.id,esc(c.name)+' · assinante desde '+opDate(s.created),`<a class="btn secondary small" href="#/admin/assinaturas">Voltar</a><button class="btn small" data-op="edit-subscription" data-id="${s.id}">Editar preferências</button>`)}<div class="admin-detail-grid"><section class="admin-panel"><div class="row between"><h2>${esc(ops.settings.clubName)}</h2>${opStatus(s.status)}</div><dl class="admin-facts"><div><dt>Mensalidade contratada</dt><dd>${money(s.price)} · frete incluído</dd></div><div><dt>Perfil e acabamento</dt><dd>${s.profile} · ${s.finish}</dd></div><div><dt>Pagamento</dt><dd>${s.payment==='card'?'Cartão de teste ···· 4242':'Pix mensal'}</dd></div><div><dt>Próxima renovação</dt><dd>${opDate(s.nextRenewal)}</dd></div></dl><div class="admin-inline-actions">${!['Cancelada','Pausada'].includes(s.status)?`<button class="btn small" data-admin="renew-cycle" data-id="${s.id}">Simular próxima renovação</button><button class="btn secondary small" data-admin="sub-status" data-status="Pausada" data-id="${s.id}">Pausar</button>`:''}${s.status==='Pausada'?`<button class="btn small" data-admin="sub-status" data-status="Ativa" data-id="${s.id}">Retomar</button>`:''}${s.status!=='Cancelada'?`<button class="text-btn danger-text" data-op="cancel-subscription" data-id="${s.id}">Cancelar</button>`:''}</div><h3 style="margin-top:28px">Edições e pedidos</h3>${adminTable(['Pedido','Edição','Valor','Situação'],list.map(o=>[`<a href="#/admin/pedidos/${o.id}" class="admin-link">${o.id}</a>`,esc(o.edition),money(o.total),opStatus(o.status)]))}</section><aside class="stack"><section class="admin-panel"><h2>Contato e destino</h2><a href="#/admin/clientes/${c.id}" class="admin-link">${esc(c.name)}</a><p>${esc(c.email)}</p><p>${esc(s.address.street)}, ${esc(s.address.number)}<br>${esc(s.address.city)}/${esc(s.address.state)} · ${esc(s.address.cep)}</p></section><section class="admin-panel"><h2>Histórico</h2><div class="admin-history">${s.history.map(h=>`<p><small>${opDate(h.date)}</small>${esc(h.label)}</p>`).join('')}</div></section></aside></div>`}
function adminClients(){const list=adminFiltered(ops.clients);return `${adminHeading('Clientes','Histórico de compras, assinaturas e atendimento.',`<button class="btn secondary small" data-admin="export" data-kind="clientes">Exportar CSV</button><button class="btn small" data-admin="new-client">${icon('plus')}Novo cliente demo</button>`)}${adminToolbar(['Todos','Ativo','Inativo'])}${adminTable(['Cliente','Contato','Localização','Clube','Compras confirmadas','Situação',''],list.map(c=>{const s=ops.subscriptions.find(x=>x.customerId===c.id&&x.status!=='Cancelada');return[`<a class="admin-link" href="#/admin/clientes/${c.id}">${esc(c.name)}</a><small>${c.id}</small>`,esc(c.email),`${esc(c.city||'—')}/${esc(c.state||'')}`,s?opStatus(s.status):'Avulso',money(ops.charges.filter(x=>x.customerId===c.id&&x.status==='Pago').reduce((a,x)=>a+x.amount,0)),opStatus(c.status),`<a class="admin-row-action" href="#/admin/clientes/${c.id}">Abrir ${icon('chevron')}</a>`]}))}`}
function adminClientDetail(id){const c=opClient(id);if(!c)return adminNotFound();const list=ops.orders.filter(o=>o.customerId===id),subs=ops.subscriptions.filter(s=>s.customerId===id);return `${adminHeading(esc(c.name),c.id+' · cliente de demonstração',`<a class="btn secondary small" href="#/admin/clientes">Voltar</a><button class="btn small" data-admin="edit-client" data-id="${id}">Editar cadastro</button>`)}<div class="admin-detail-grid"><section class="admin-panel"><h2>Histórico de relacionamento</h2><div class="admin-client-metrics"><div><strong>${list.length}</strong><span>pedidos</span></div><div><strong>${money(ops.charges.filter(x=>x.customerId===id&&x.status==='Pago').reduce((a,x)=>a+x.amount,0))}</strong><span>recebimentos simulados</span></div><div><strong>${subs.length}</strong><span>assinaturas</span></div></div>${adminTable(['Pedido','Origem','Total','Situação'],list.map(o=>[`<a class="admin-link" href="#/admin/pedidos/${o.id}">${o.id}</a>`,o.type,money(o.total),opStatus(o.status)]))}<h3 style="margin-top:27px">Assinaturas</h3>${subs.length?subs.map(s=>`<a class="admin-client-sub" href="#/admin/assinaturas/${s.id}"><span>${s.id} · cesta ${s.profile.toLowerCase()}</span>${opStatus(s.status)}${icon('chevron')}</a>`).join(''):'<p class="admin-note">Cliente sem assinatura.</p>'}</section><aside class="admin-panel"><h2>Cadastro</h2>${opStatus(c.status)}<p>${esc(c.email)}<br>${esc(c.phone||'Telefone não informado')}</p><p>${esc(c.street||'Endereço não informado')}, ${esc(c.number||'')}<br>${esc(c.city||'')}/${esc(c.state||'')} · ${esc(c.cep||'')}</p><h3 style="margin-top:23px">Nota interna</h3><p>${esc(c.notes||'Nenhuma anotação.')}</p><button class="btn secondary full small" data-admin="archive-client" data-id="${id}">${c.status==='Ativo'?'Arquivar cadastro':'Reativar cadastro'}</button></aside></div>`}
function adminProduction(){const stages=['Fila','Impressão','Acabamento','Conferência'];return `${adminHeading('Produção','Da fila de impressão ao cuidado com cada peça.',`<button class="btn secondary small" data-admin="export" data-kind="producao">Exportar fila</button><button class="btn small" data-admin="new-job">${icon('plus')}Nova ordem de produção</button>`)}<div class="admin-printers">${ops.printers.map(p=>`<div><span>${icon('box')}<strong>${esc(p.name)}</strong></span>${opStatus(p.status)}<button class="text-btn" data-admin="printer-state" data-id="${p.id}">Alterar situação</button></div>`).join('')}</div><div class="production-board">${stages.map((stage,i)=>{const list=ops.jobs.filter(j=>j.stage===stage);return `<section><div class="production-column-head"><h2>${stage}</h2><span>${list.length}</span></div>${list.map(j=>{const o=opOrder(j.orderId);return `<article class="production-job"><div class="row between">${opStatus(j.priority==='Alta'?'Prioridade alta':'Normal')}<small>${j.id}</small></div><h3>${esc(o?.items[0]?.name||'Cesta do clube')}</h3><a href="#/admin/pedidos/${j.orderId}">${j.orderId}</a><p>${esc(opClient(o?.customerId)?.name||'Cliente')}<br>${esc(j.printer)}</p><div class="row between"><small>${j.hours}h estimadas · ${esc(j.assignee)}</small><small>${opDate(j.due)}</small></div><button class="btn secondary full small" data-admin="advance-job" data-id="${j.id}">${i===3?'Aprovar para expedição':'Mover para '+stages[i+1]} ${icon('arrow')}</button></article>`}).join('')||'<p class="production-empty">Sem ordens nesta etapa.</p>'}</section>`}).join('')}</div><section class="admin-panel" style="margin-top:24px"><h2>Pedidos confirmados aguardando uma ordem</h2>${adminTable(['Pedido','Cliente','Itens',''],ops.orders.filter(o=>o.status==='Confirmado'&&!ops.jobs.some(j=>j.orderId===o.id&&j.stage!=='Pronto')).map(o=>[`<a class="admin-link" href="#/admin/pedidos/${o.id}">${o.id}</a>`,esc(opClient(o.customerId)?.name),o.items.map(x=>esc(x.name)).join(', '),`<button class="btn small" data-admin="production-add" data-id="${o.id}">Criar ordem</button>`]))}</section>`}
function adminShipping(){const list=adminFiltered(ops.orders.filter(o=>['Pronto para envio','Enviado','Entregue'].includes(o.status)));return `${adminHeading('Expedição e envios','Prepare a etiqueta, simule o despacho e acompanhe a entrega.',`<button class="btn secondary small" data-admin="export" data-kind="envios">Exportar envios</button>`)}${adminStats([['Prontos para envio',ops.orders.filter(o=>o.status==='Pronto para envio').length],['Em trânsito',ops.orders.filter(o=>o.status==='Enviado').length],['Entregues',ops.orders.filter(o=>o.status==='Entregue').length],['Frete do clube','Incluído','Regra de demonstração']])}${adminToolbar(['Todos','Pronto para envio','Enviado','Entregue','Clube','Loja'])}${adminTable(['Pedido / cliente','Destino','Transportadora / rastreio','Previsão','Situação','Ação'],list.map(o=>[`<a class="admin-link" href="#/admin/pedidos/${o.id}">${o.id}</a><small>${esc(opClient(o.customerId)?.name)}</small>`,`${esc(o.address.city)}/${esc(o.address.state)}`,`${esc(o.carrier||'A definir')}<small>${esc(o.tracking||'Sem rastreio')}</small>`,opDate(o.due),opStatus(o.status),o.status==='Pronto para envio'?`<button class="btn small" data-admin="ship-order" data-id="${o.id}">Preparar envio</button>`:o.status==='Enviado'?`<button class="btn secondary small" data-admin="delivered" data-id="${o.id}">Simular entrega</button>`:`<button class="text-btn" data-admin="label" data-id="${o.id}">Ver etiqueta</button>`]))}`}
function adminFinance(){const f=adminMoneyStats(),list=adminFiltered(ops.charges);return `${adminHeading('Financeiro','Recebimentos, cobranças, despesas e resultado da simulação.',`<button class="btn secondary small" data-admin="export" data-kind="financeiro">Exportar transações</button><button class="btn small" data-admin="new-expense">${icon('plus')}Registrar despesa</button>`)}${adminStats([['Recebido',money(f.paid),'Cobranças com situação Pago'],['A receber',money(f.pending),'Pendentes e recusadas'],['Despesas pagas',money(f.expenses),'Saídas registradas'],['Resultado simulado',money(f.paid-f.expenses),'Recebimentos menos despesas pagas']])}<section class="admin-panel"><h2>Cobranças e transações</h2>${adminToolbar(['Todos','Pago','Pendente','Recusado','Estornado','Cancelada'])}${adminTable(['Cobrança / descrição','Cliente','Vencimento','Método','Valor','Situação',''],list.map(c=>[`<strong>${c.id}</strong><small>${esc(c.description)}</small>`,esc(opClient(c.customerId)?.name),opDate(c.due),c.method==='card'?'Cartão de teste':'Pix / demo',money(c.amount),opStatus(c.status),['Pendente','Recusado'].includes(c.status)?`<button class="btn small" data-admin="pay-charge" data-id="${c.id}">Simular recebimento</button>`:c.status==='Pago'?`<button class="text-btn" data-admin="refund-charge" data-id="${c.id}">Simular estorno</button>`:`<button class="text-btn" data-op="receipt" data-id="${c.id}">Comprovante</button>`]))}</section><section class="admin-panel" style="margin-top:24px"><div class="admin-panel-heading"><h2>Despesas e compromissos</h2><small>Sem movimentação bancária real</small></div>${adminTable(['Descrição','Centro de custo','Data','Valor','Situação',''],ops.expenses.map(d=>[esc(d.name),esc(d.category),opDate(d.date),money(d.amount),opStatus(d.status),d.status==='Previsto'?`<button class="text-btn" data-admin="pay-expense" data-id="${d.id}">Marcar como paga</button>`:'—']))}</section>`}
function adminProducts(){const list=products.filter(p=>!adminState.search||p.name.toLowerCase().includes(adminState.search.toLowerCase()));return `${adminHeading('Produtos e estoque','Preços, disponibilidade e referências usadas pela loja e pelo clube.',`<button class="btn secondary small" data-admin="export" data-kind="produtos">Exportar catálogo</button><button class="btn small" data-admin="new-product">${icon('plus')}Novo produto demo</button>`)}${adminToolbar(['Todos'])}${adminTable(['Produto / SKU','Coleção','Preço','Estoque','Disponibilidade',''],list.map(p=>{const inv=ops.inventory[p.id]||{stock:0,sku:'—'};return [`<div class="admin-product-cell">${photo(p.img,'',p.name)}<span><strong>${esc(p.name)}</strong><small>${esc(inv.sku)}</small></span></div>`,esc(p.category),money(p.price),`<span class="${inv.stock<=ops.settings.lowStock?'danger-text':''}">${inv.stock} un.</span>`,opStatus(p.active===false?'Inativo':'Ativo'),`<button class="btn secondary small" data-admin="edit-product" data-id="${p.id}">Editar</button>`]}))}`}
function adminEditions(){return `${adminHeading('Edição mensal do clube','Defina a curadoria, os perfis e o dia de expedição.')}<div class="admin-detail-grid"><section class="admin-panel"><form data-form="edition" class="stack"><div class="form-grid"><label>Mês da edição<input type="month" name="month" required value="${ops.settings.editionMonth}"></label><label>Dia previsto de expedição<input type="number" name="dispatchDay" min="1" max="28" required value="${ops.settings.dispatchDay}"></label><label class="span2">Nome da edição<input name="edition" required value="${esc(ops.settings.edition)}"></label></div>${['Católica','Evangélica','Cristã'].map(profile=>`<fieldset class="edition-profile"><legend>Cesta ${profile.toLowerCase()}</legend><div>${products.filter(p=>p.active!==false).map(p=>`<label><input type="checkbox" name="items-${profile}" value="${p.id}" ${(ops.settings.profiles[profile]||[]).includes(p.id)?'checked':''}>${esc(p.name)}</label>`).join('')}</div></fieldset>`).join('')}<div class="notice">A curadoria atualizada é usada nos próximos ciclos gerados. Pedidos já criados mantêm seus itens.</div><button class="btn">Salvar edição de demonstração</button></form></section><aside class="admin-panel"><img class="admin-edition-image" src="assets/club-basket.png" alt="Cesta mensal conceitual"><h2>${esc(ops.settings.edition)}</h2><p>${opMonth(ops.settings.editionMonth+'-08')} · envio previsto no dia ${ops.settings.dispatchDay}</p><div class="money-line"><span>Valor do plano</span><strong>${money(ops.settings.price)}/mês</strong></div><a class="btn secondary full small" href="#/clube">Visualizar página do clube</a></aside></div>`}
function adminSupport(id){const list=adminFiltered(ops.tickets),t=ops.tickets.find(x=>x.id===id)||list[0];return `${adminHeading('Atendimentos','Acompanhe as conversas com os clientes no mesmo lugar.')}<div class="admin-support-layout"><aside class="admin-panel ticket-inbox">${adminToolbar(['Todos','Aberto','Em atendimento','Resolvido'])}${list.map(x=>`<a href="#/admin/suporte/${x.id}" class="${t?.id===x.id?'selected':''}"><div class="row between"><strong>${esc(opClient(x.customerId)?.name||'Cliente')}</strong>${opStatus(x.status)}</div><span>${esc(x.subject)}</span><small>${x.id} · ${opDate(x.created)}</small></a>`).join('')||'<p>Nenhum atendimento com esses filtros.</p>'}</aside><section class="admin-panel">${t?`<div class="row between wrap"><div><h2>${esc(t.subject)}</h2><p>${t.id} · ${esc(t.category)} · ${esc(opClient(t.customerId)?.name)}</p></div>${opStatus(t.status)}</div><div class="ticket-thread">${t.messages.map(m=>`<div class="ticket-message ${m.by==='equipe'?'staff':''}"><strong>${m.by==='equipe'?'Equipe Mãos em Oração':'Cliente'}</strong><p>${esc(m.text)}</p><small>${opDate(m.date)}</small></div>`).join('')}</div><form data-form="admin-reply" data-id="${t.id}" class="stack"><label>Resposta de demonstração<textarea name="message" required minlength="3" maxlength="1500" placeholder="Escreva uma resposta acolhedora."></textarea></label><div class="form-grid"><label>Situação<select name="status">${['Aberto','Em atendimento','Resolvido'].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select></label><label>Responsável<select name="assignee">${ops.team.filter(x=>x.status==='Ativo').map(u=>`<option ${u.name.split(' ')[0]===t.assignee?'selected':''}>${u.name.split(' ')[0]}</option>`).join('')}</select></label></div><small class="muted">A resposta aparece apenas neste atendimento local e na área do cliente da demonstração.</small><button class="btn">Salvar resposta e situação</button></form>`:'<div class="admin-empty">Selecione um atendimento para ler a conversa.</div>'}</section></div>`}
function adminCommunity(){const list=[...prayerPosts,...prayerExamples];return `${adminHeading('Mural de orações','Moderação local dos pedidos publicados no Cantinho da Fé.',`<a class="btn secondary small" href="#/cantinho-da-fe">Ver mural ${icon('arrow')}</a>`)}<div class="notice" style="margin-bottom:23px">Nenhum pedido é publicado na internet neste protótipo. Exemplos ficam identificados; a moderação apenas oculta ou restaura o registro local.</div>${adminTable(['Pedido','Autor','Tema','Origem','Visibilidade',''],list.map(p=>[`${esc(p.title)}<small>${esc(p.message.slice(0,100))}…</small>`,esc(p.anonymous?'Anônimo':p.name),p.category,p.example?'Exemplo':'Pedido local',opStatus(hiddenPrayers.includes(p.id)?'Oculto':'Publicado'),`<button class="btn secondary small" data-admin="moderate" data-id="${p.id}">${hiddenPrayers.includes(p.id)?'Restaurar':'Ocultar'}</button>`]))}`}
function adminMarketing(){const sub=readStore('newsletter',null);return `${adminHeading('Oração diária','Prepare mensagens de acolhimento e explore o fluxo de envio demonstrativo.')}<div class="admin-detail-grid"><section class="admin-panel"><h2>Preparar uma oração</h2><form data-form="campaign" class="stack" style="margin-top:22px"><label>Assunto<input name="subject" required minlength="5" value="Uma oração para começar o seu dia"></label><label>Oração autoral<textarea name="message" required minlength="20" maxlength="2000" placeholder="Escreva uma oração breve e acolhedora."></textarea></label><label>Data de referência<input type="date" name="date" required value="${OPS_DAY}"></label><div class="notice">Nenhum e-mail será enviado. A ação registra uma campanha de demonstração no painel.</div><button class="btn">Simular envio da oração ${icon('mail')}</button></form></section><aside class="admin-panel"><h2>Inscrição neste navegador</h2>${sub?.subscribed?`<p>${esc(sub.name||'Inscrição de demonstração')}<br>${esc(sub.email)}</p>${opStatus('Ativo')}`:'<p>Não há inscrição ativa de demonstração neste navegador.</p>'}<button class="btn secondary full small" data-action="newsletter">Ver popup de inscrição</button><h3 style="margin-top:28px">Envios de demonstração</h3>${ops.campaigns.length?ops.campaigns.map(x=>`<div class="campaign-history"><strong>${esc(x.subject)}</strong><small>${opDate(x.date)} · ${x.recipients} destinatário(s) local(is) · simulado</small></div>`).join(''):'<p>Nenhum envio simulado por aqui.</p>'}</aside></div>`}
function adminReports(){const f=adminMoneyStats();return `${adminHeading('Relatórios','Leituras da operação a partir dos registros desta demonstração.')}<div class="admin-reports-grid"><section class="admin-panel"><h2>Vendas e recebimentos</h2><dl class="admin-facts"><div><dt>Recebimentos pagos</dt><dd>${money(f.paid)}</dd></div><div><dt>Pedidos criados</dt><dd>${ops.orders.length}</dd></div><div><dt>Ticket médio dos pedidos</dt><dd>${money(ops.orders.length?ops.orders.reduce((a,x)=>a+x.total,0)/ops.orders.length:0)}</dd></div></dl><button class="btn secondary full small" data-admin="export" data-kind="pedidos">Baixar relatório de pedidos</button></section><section class="admin-panel"><h2>Clube e recorrência</h2><dl class="admin-facts"><div><dt>Contratos ativos</dt><dd>${ops.subscriptions.filter(s=>s.status==='Ativa').length}</dd></div><div><dt>Receita mensal projetada</dt><dd>${money(f.mrr)}</dd></div><div><dt>Contratos cancelados</dt><dd>${ops.subscriptions.filter(s=>s.status==='Cancelada').length}</dd></div></dl><button class="btn secondary full small" data-admin="export" data-kind="assinaturas">Baixar relatório do clube</button></section><section class="admin-panel"><h2>Produção e entrega</h2><dl class="admin-facts"><div><dt>Ordens abertas</dt><dd>${ops.jobs.filter(j=>j.stage!=='Pronto').length}</dd></div><div><dt>Horas estimadas abertas</dt><dd>${ops.jobs.filter(j=>j.stage!=='Pronto').reduce((a,j)=>a+j.hours,0)}h</dd></div><div><dt>Pedidos entregues</dt><dd>${ops.orders.filter(o=>o.status==='Entregue').length}</dd></div></dl><button class="btn secondary full small" data-admin="export" data-kind="producao">Baixar fila de produção</button></section></div>`}
function adminTeam(){return `${adminHeading('Equipe e perfis','Cadastros e funções ilustrativas do painel. Não há autenticação real.',`<button class="btn small" data-admin="new-team">${icon('plus')}Adicionar integrante demo</button>`)}${adminTable(['Integrante','E-mail de demonstração','Perfil','Situação',''],ops.team.map(u=>[esc(u.name),esc(u.email),esc(u.role),opStatus(u.status),`<button class="btn secondary small" data-admin="edit-team" data-id="${u.id}">Editar perfil</button>`]))}<div class="notice" style="margin-top:24px">Perfis e permissões são demonstrativos. O endereço do administrador não protege dados de produção.</div>`}
function adminSettings(){return `${adminHeading('Configurações','Ajustes da marca, do plano mensal e da operação de demonstração.')}<div class="admin-detail-grid"><section class="admin-panel"><form data-form="settings" class="stack"><h2>Loja e atendimento</h2><div class="form-grid"><label class="span2">Nome da loja<input name="storeName" required value="${esc(ops.settings.storeName)}"></label><label>E-mail demonstrativo<input name="email" type="email" required value="${esc(ops.settings.email)}"></label><label>Telefone fictício<input name="phone" value="${esc(ops.settings.phone)}"></label></div><h2>Plano mensal único</h2><div class="form-grid"><label class="span2">Nome do clube<input name="clubName" required value="${esc(ops.settings.clubName)}"></label><label>Mensalidade para novas assinaturas<input name="price" type="number" required min="1" step=".01" value="${ops.settings.price}"></label><label>Dia da expedição mensal<input name="dispatchDay" type="number" required min="1" max="28" value="${ops.settings.dispatchDay}"></label><label>Alerta de estoque baixo<input name="lowStock" type="number" required min="0" value="${ops.settings.lowStock}"></label></div><div class="notice">O preço editado vale para novas assinaturas. Contratos existentes preservam a mensalidade da adesão. Frete segue incluído no plano demonstrativo.</div><button class="btn">Salvar configurações</button></form></section><aside class="stack"><section class="admin-panel"><h2>Serviços</h2><div class="integration-status"><span>Cartão e Pix</span>${opStatus('Simulado')}</div><div class="integration-status"><span>Transportadora</span>${opStatus('Simulado')}</div><div class="integration-status"><span>E-mail de oração</span>${opStatus('Simulado')}</div><div class="integration-status"><span>Armazenamento</span><strong>Neste navegador</strong></div><p>Este painel não contém chaves de serviços nem realiza cobrança, envio ou comunicação real.</p></section><section class="admin-panel"><h2>Rastreabilidade</h2><p>Alterações locais ficam registradas no histórico da operação.</p><a class="btn secondary full small" href="#/admin/atividade">Ver atividade da operação</a></section></aside></div>`}
function adminAuditList(limit=100){return `<div class="admin-audit">${ops.audit.slice(0,limit).map(a=>`<div><span>${icon('check')}</span><p><strong>${esc(a.action)}</strong><small>${esc(a.actor)} · ${esc(a.entity)}</small></p><time>${new Date(a.date).toLocaleString('pt-BR')}</time></div>`).join('')}</div>`}
function adminActivity(){return `${adminHeading('Atividade da operação','Histórico de alterações feitas nesta demonstração.')}<section class="admin-panel">${adminAuditList()}</section>`}
function adminGlobalResults(){const q=adminState.globalSearch.toLowerCase(),cs=ops.clients.filter(c=>(c.name+' '+c.email+' '+c.id).toLowerCase().includes(q)),os=ops.orders.filter(o=>(o.id+' '+opClient(o.customerId)?.name).toLowerCase().includes(q)),ss=ops.subscriptions.filter(s=>(s.id+' '+opClient(s.customerId)?.name).toLowerCase().includes(q));return `${adminHeading('Busca por “'+esc(adminState.globalSearch)+'”','Resultados da operação de demonstração.')}<section class="admin-panel"><h2>Clientes</h2>${adminTable(['Cliente','Contato'],cs.map(c=>[`<a class="admin-link" href="#/admin/clientes/${c.id}">${esc(c.name)}</a>`,esc(c.email)]))}<h2 style="margin-top:26px">Pedidos</h2>${adminTable(['Pedido','Cliente','Situação'],os.map(o=>[`<a href="#/admin/pedidos/${o.id}" class="admin-link">${o.id}</a>`,esc(opClient(o.customerId)?.name),opStatus(o.status)]))}<h2 style="margin-top:26px">Assinaturas</h2>${adminTable(['Contrato','Cliente','Situação'],ss.map(s=>[`<a class="admin-link" href="#/admin/assinaturas/${s.id}">${s.id}</a>`,esc(opClient(s.customerId)?.name),opStatus(s.status)]))}</section>`}
function adminNotFound(){return `<div class="empty"><h1>Registro não encontrado.</h1><a class="btn" href="#/admin">Voltar à visão geral</a></div>`}
